    <motion.a
      href={item.url}
      target="_blank"
      rel="noopener noreferrer"
      style={{
        backgroundColor: "#fff",
        borderRadius: "15px",
        overflow: "hidden",
        boxShadow: "0 5px 15px rgba(0, 0, 0, 0.08)",
        transition: "all 0.3s ease",
        cursor: "pointer",
        position: "relative",
        textDecoration: "none",
        display: "block",
      }}
      variants={variants}
      whileHover={{
        y: -8,
        boxShadow: "0 15px 30px rgba(0, 0, 0, 0.15)",
      }}
    >
      {/* Info */}
      <div style={{ padding: "20px" }}>
        <h3
          style={{
            fontSize: "1.1rem",
            fontWeight: 600,
            color: "#333",
            margin: "0 0 12px",
