            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
          }}
        >
          {item.title}
        </h3>
        <div style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
          fontSize: "0.9rem",
          color: "#6c757d",
        }}>
          <i className="fas fa-calendar-alt" style={{ color: "#667eea" }}></i>
          <span>{item.pubdate}</span>
        </div>
        <div style={{
          marginTop: "12px",
          paddingTop: "12px",
          borderTop: "1px solid #e9ecef",
        }}>
          <span style={{
            fontSize: "0.85rem",
            color: "#667eea",
            fontWeight: 600,
            display: "flex",
            alignItems: "center",
            gap: "5px",
          }}>
            자세히 보기
            <i className="fas fa-arrow-right"></i>
          </span>
        </div>
      </div>
    </motion.a>
  );
}

export default LibraryPage;
